KG42.register("clusters-2e34df92fd1c9e36e7d4da74",{"id":"11-p2p_mechanisms_evaluation::v142-d-K004","paper":"11-p2p_mechanisms_evaluation","label":"Branch-specific pricing, surplus and deficit trading, and cost and revenue allocation driven by MMR component submissions","record":{"cluster_id":"v142-d-K004","label":"Branch-specific pricing, surplus and deficit trading, and cost and revenue allocation driven by MMR component submissions","market_meaning":"Participants submit demand and generation components separately, and the coordinator calculates MMR buying and selling prices according to regional supply-demand balance, shortage, or surplus; imports to cover shortages correspond to cost recovery, and exports of surplus correspond to revenue distribution among suppliers. The product-design explanation provides the context for sharing surplus generation, while generation sign conventions and decision-model interfaces still require clarification.","mechanism_ids":["v141-a-M02"],"market_types":["LEM"],"process_stages":["bidding","pricing","activation","settlement"],"scope_disposition":"unresolved","scope_explanation":"All bindings remain within the M02 scope and apply separately under the three supply-demand branches. The design purpose and evaluation of the low-EV scenario in R015 are neither participation restrictions nor pricing conditions. The relationship between the discharge signs in A24 and A3 within the same mechanism remains unexplained, so complete consistency between participant decisions and cost and revenue calculations cannot be claimed.","assembly_status":"partial","boundary_rationale":"Component submissions directly determine regional surpluses and deficits, external trading, and price adjustments, forming an economic rule spanning submission, pricing, execution, and payment; the repeated price expressions in R016 only supplement the cost and revenue interpretation and are not counted as independent pricing rules.","chain_bindings":[{"chain_id":"v141-c-R011","ownership":"primary","role":"core","rationale":"Provides the separate-submission requirement and the source of the demand component."},{"chain_id":"v141-c-R012","ownership":"primary","role":"core","rationale":"Provides the generation-submission definition complementary to the demand component, retaining the existing notation without rewriting it."},{"chain_id":"v141-c-R013","ownership":"primary","role":"core","rationale":"Translates supply-demand imbalance conditions into activities involving imports from or exports to the retailer."},{"chain_id":"v141-c-R014","ownership":"primary","role":"core","rationale":"Provides the main rule under which the coordinator generates internal buying and selling prices according to the three regional balance conditions."},{"chain_id":"v141-c-R015","ownership":"primary","role":"context","rationale":"Retains the design purpose of sharing surplus generation and the comparative context solely as explanatory background, without introducing additional operating conditions."},{"chain_id":"v141-c-R016","ownership":"primary","role":"support","rationale":"Supplements the obligations to cover deficit costs and distribute surplus revenue; its A26/A27 are retained in association with R014, rather than treated as another set of price formulas."}],"connections":[{"connection_id":"v142-d-K004-CN01","from_chain_id":"v141-c-R011","to_chain_id":"v141-c-R012","kind":"complementary_scope","from_refs":["v141-c-R011::phi::v141-c-R011-C001","v141-c-R011::phi::v141-c-R011-C002"],"to_refs":["v141-c-R012::phi::v141-c-R012-C001","v141-c-R012::phi::v141-c-R012-C002"],"evidence_ids":["v141-b-g07-ev-06"],"rationale":"A24 explicitly requires demand and generation to be provided separately for each time period; the two chains jointly constitute this submission content and cannot be collapsed into SDR-style net demand."},{"connection_id":"v142-d-K004-CN02","from_chain_id":"v141-c-R011","to_chain_id":"v141-c-R014","kind":"quantity_interface","from_refs":["v141-c-R011::x::v141-c-R011-x-dem-bid-t","v141-c-R011::phi::v141-c-R011-C002"],"to_refs":["v141-c-R014::theta::e_dem_bid_nt","v141-c-R014::phi::v141-c-R014-C002"],"evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07"],"rationale":"The demand profile submitted by an individual participant enters MMR pricing after all bids have been collected; submission outputs and pricing inputs retain distinct local roles and indices."},{"connection_id":"v142-d-K004-CN03","from_chain_id":"v141-c-R012","to_chain_id":"v141-c-R014","kind":"quantity_interface","from_refs":["v141-c-R012::phi::v141-c-R012-C002"],"to_refs":["v141-c-R014::theta::e_gen_bid_nt","v141-c-R014::phi::v141-c-R014-C001"],"evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07"],"rationale":"The generation component in A24 is a bid input to A25-A27. R012 has no typed generation-bid output, so the interface is established from the existing defining expression without mistaking the EV discharge variable for the entire generation component."},{"connection_id":"v142-d-K004-CN04","from_chain_id":"v141-c-R014","to_chain_id":"v141-c-R013","kind":"functional_coupling","from_refs":["v141-c-R014::phi::v141-c-R014-C005","v141-c-R014::phi::v141-c-R014-C006"],"to_refs":["v141-c-R013::phi::v141-c-R013-C001","v141-c-R013::phi::v141-c-R013-C002"],"evidence_ids":["v141-b-g07-ev-07"],"rationale":"The source explicitly explains the corresponding price adjustments in terms of imports to cover deficits and exports of surplus; the two chains connect under the same time period, region, and imbalance branch. No precedence or implication edges are added based on narrative order."},{"connection_id":"v142-d-K004-CN05","from_chain_id":"v141-c-R013","to_chain_id":"v141-c-R016","kind":"functional_coupling","from_refs":["v141-c-R013::phi::v141-c-R013-C001","v141-c-R013::phi::v141-c-R013-C002"],"to_refs":["v141-c-R016::phi::v141-c-R016-C001","v141-c-R016::phi::v141-c-R016-C002"],"evidence_ids":["v141-b-g07-ev-07"],"rationale":"Import expenditures and export revenues correspond respectively to the payment meanings of cost recovery and revenue distribution, retaining the deficit and surplus branches without fabricating independent cash-flow equations."},{"connection_id":"v142-d-K004-CN06","from_chain_id":"v141-c-R014","to_chain_id":"v141-c-R016","kind":"alternative_representation","from_refs":["v141-c-R014::phi::v141-c-R014-C005"],"to_refs":["v141-c-R016::phi::v141-c-R016-C001"],"evidence_ids":["v141-b-g07-ev-07"],"rationale":"Both retain the same A26 price relationship and the same deficit condition, presenting pricing and cost-recovery meanings respectively; they are displayed in association without counting an additional independent mathematical rule."},{"connection_id":"v142-d-K004-CN07","from_chain_id":"v141-c-R014","to_chain_id":"v141-c-R016","kind":"alternative_representation","from_refs":["v141-c-R014::phi::v141-c-R014-C006"],"to_refs":["v141-c-R016::phi::v141-c-R016-C002"],"evidence_ids":["v141-b-g07-ev-07"],"rationale":"Both retain the same A27 price relationship and the same surplus condition, reflecting pricing and export-revenue distribution respectively; no payment edges are fabricated on this basis."},{"connection_id":"v142-d-K004-CN08","from_chain_id":"v141-c-R015","to_chain_id":"v141-c-R014","kind":"complementary_scope","from_refs":["v141-c-R015::phi::v141-c-R015-C001","v141-c-R015::phi::v141-c-R015-C002"],"to_refs":["v141-c-R014::phi::v141-c-R014-C003"],"evidence_ids":["v141-b-g06-e10","v141-b-g07-ev-07"],"rationale":"The design purpose helps explain the economic scope of the MMR pricing model and serves only as a background association; no pricing dependencies are added based on performance under low EV levels or the description that flexible demand is not specifically incentivized, nor is the BS mechanism merged."}],"object_mappings":[{"mapping_id":"v142-d-K004-OM01","kind":"same_node","member_refs":["v141-c-R011::V::bidding.demand","v141-c-R014::V::bidding.demand"],"canonical_ref":"v141-c-R011::V::bidding.demand","display_policy":"single_representative","evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07"],"rationale":"All represent the function of submitting a separate demand component under M02 and are not normalized across scopes with identically named nodes in other mechanisms."},{"mapping_id":"v142-d-K004-OM02","kind":"same_node","member_refs":["v141-c-R012::V::bidding.supply","v141-c-R014::V::bidding.supply"],"canonical_ref":"v141-c-R012::V::bidding.supply","display_policy":"single_representative","evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07"],"rationale":"All refer to the submission function for the M02 generation component; the question concerning the sign of the supply quantity remains and is not resolved by node identity."},{"mapping_id":"v142-d-K004-OM03","kind":"same_quantity","member_refs":["v141-c-R011::x::v141-c-R011-x-dem-bid-t","v141-c-R013::theta::v141-c-R013-T004","v141-c-R014::theta::e_dem_bid_nt"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07"],"rationale":"After the individual-participant profile in R011 is instantiated for participant n, its demand bids correspond item by item to the submitted inputs for execution and pricing; the output role of x and input role of theta are retained, without rewriting a single profile as an array for all participants."},{"mapping_id":"v142-d-K004-OM04","kind":"same_quantity","member_refs":["v141-c-R013::theta::v141-c-R013-T003","v141-c-R014::theta::e_gen_bid_nt"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07"],"rationale":"Both are the submitted generation component for the same MMR participant and time period, serving execution and pricing respectively; neither discharge power nor its absolute value is additionally treated as the same object."},{"mapping_id":"v142-d-K004-OM05","kind":"same_quantity","member_refs":["v141-c-R013::theta::v141-c-R013-T001","v141-c-R014::theta::r_retail_t","v141-c-R016::theta::v141-c-R016-P01"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g07-ev-07"],"rationale":"The retail price for the same MMR deficit trade is used for imports, price adjustment, and cost recovery; all three local parameters and their uses are retained in full."},{"mapping_id":"v142-d-K004-OM06","kind":"same_quantity","member_refs":["v141-c-R013::theta::v141-c-R013-T002","v141-c-R014::theta::r_export_t","v141-c-R016::theta::v141-c-R016-P02"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g07-ev-07"],"rationale":"The export price for the same MMR surplus trade enters exports, price adjustment, and revenue distribution respectively; identical numerical prices are not presumed across mechanisms."},{"mapping_id":"v142-d-K004-OM07","kind":"same_quantity","member_refs":["v141-c-R014::theta::r_average_t","v141-c-R016::theta::v141-c-R016-P03"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g07-ev-07"],"rationale":"Both reference the intermediate price for the same time period defined by A25, retaining their local roles as a pricing parameter and an input to the payment interpretation."},{"mapping_id":"v142-d-K004-OM08","kind":"same_expression","member_refs":["v141-c-R014::phi::v141-c-R014-C005","v141-c-R016::phi::v141-c-R016-C001"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g07-ev-07"],"rationale":"The term-by-term content and deficit condition correspond to the same A26 expression. Because pricing and payment interpretation have different responsibilities, both constraint objects are retained and their repeated mathematical content is linked."},{"mapping_id":"v142-d-K004-OM09","kind":"same_expression","member_refs":["v141-c-R014::phi::v141-c-R014-C006","v141-c-R016::phi::v141-c-R016-C002"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g07-ev-07"],"rationale":"The term-by-term content and surplus condition correspond to the same A27 expression; duplication is not identified solely on the basis of shared evidence, and both local interpretations and all original source objects remain accessible."}],"gaps":[{"gap_id":"v142-d-K004-G01","category":"unverified_source","description":"A24-A27 and the design purpose are all unreviewed candidate transcriptions; quantity correspondences and the identification of repeated expressions in this cluster do not mean that the original scientific content has been verified.","chain_ids":["v141-c-R011","v141-c-R012","v141-c-R013","v141-c-R014","v141-c-R015","v141-c-R016"],"object_refs":[],"evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07","v141-b-g06-e10"],"proposal_ids":[],"required_work":"Independently check the symbols, absolute values, conditions, and narrative attribution of A24-A27, and manually examine this cluster's assembly boundaries."},{"gap_id":"v142-d-K004-G02","category":"ambiguous_mapping","description":"There is an unexplained sign difference between the combination of the discharge and PV terms in the generation component of A24 and their combination in the electricity-sales revenue term of A3 within the same mechanism. The existing M02 bid evidence does not define the discharge sign, and device constraints registered under M01 cannot automatically resolve this question.","chain_ids":["v141-c-R012","v141-c-R013","v141-c-R014","v141-c-R016"],"object_refs":["v141-c-R012::x::v141-c-R012-V001","v141-c-R012::phi::v141-c-R012-C002","v141-c-R013::theta::v141-c-R013-T003","v141-c-R014::theta::e_gen_bid_nt","v141-c-R016::phi::v141-c-R016-C002"],"evidence_ids":["v141-b-g07-ev-02","v141-b-g07-ev-06","v141-b-g07-ev-07"],"proposal_ids":[],"required_work":"Obtain additional device-variable sign conventions within the M02 scope and check the original signs and revenue interpretations in A3 and A24; clarify their consistency upstream. D does not rewrite the existing expressions."},{"gap_id":"v142-d-K004-G03","category":"math_incomplete","description":"The demand component, power and energy units, and device-variable domains are not fully specified. The strict deficit condition in A26 already makes the demand denominator positive; excluding a zero generation denominator in A27 still requires clarification of applicable-domain conditions such as nonnegative demand. The case in which both supply and demand are zero already falls under A25, and no separate handling branch may be invented.","chain_ids":["v141-c-R011","v141-c-R012","v141-c-R014","v141-c-R016"],"object_refs":["v141-c-R011::x::v141-c-R011-x-dem-bid-t","v141-c-R011::phi::v141-c-R011-C002","v141-c-R012::phi::v141-c-R012-C002","v141-c-R014::phi::v141-c-R014-C004","v141-c-R014::phi::v141-c-R014-C005","v141-c-R014::phi::v141-c-R014-C006"],"evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07"],"proposal_ids":[],"required_work":"Complete the explanations of variable domains, units, and time-step conversions within the same mechanism, and check the computable domain of each branch; do not automatically supply parameter values or boundary formulas on the basis of common physical conventions."},{"gap_id":"v142-d-K004-G04","category":"upstream_missing","description":"R012 lacks an independent generation-bid output object, and R016 lacks typed references to its bids and prices and the corresponding graph interfaces. The existing mathematics in R016 remains a payment interpretation of the price expressions in R014, with no independent household-level payment equations.","chain_ids":["v141-c-R012","v141-c-R014","v141-c-R016"],"object_refs":["v141-c-R012::phi::v141-c-R012-C002","v141-c-R014::x::p_buy_t","v141-c-R014::x::p_sell_t","v141-c-R016::phi::v141-c-R016-C001","v141-c-R016::phi::v141-c-R016-C002"],"evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07"],"proposal_ids":[],"required_work":"Decide upstream whether to add typed references within the same mechanism and graph interfaces supported by sources; if complete payment is claimed, additional cash-flow provisions must be obtained. Existing D connections do not replace revisions to the C graph, nor do they double-count A26/A27."}]},"rule_refs":["11-p2p_mechanisms_evaluation::v141-c-R011","11-p2p_mechanisms_evaluation::v141-c-R012","11-p2p_mechanisms_evaluation::v141-c-R013","11-p2p_mechanisms_evaluation::v141-c-R014","11-p2p_mechanisms_evaluation::v141-c-R015","11-p2p_mechanisms_evaluation::v141-c-R016"],"unresolved_rule_refs":[],"node_ids":["COMP-17c4468d6b673af7","COMP-221ff4096aa50456","COMP-80212c4bda48caf5","COMP-c6917f781ea3f39e","KG31-8571e493b8ecf84a","KG31-b9a1f3b2c60ed604","KG31-bfbef4359354d09f"]});
